code='''def transform(grid):
    a = [row[:] for row in grid]
    h, w = len(a), len(a[0])
    from collections import Counter
    bg = Counter(v for row in a for v in row).most_common(1)[0][0]
    sep_rows = [(r, a[r][0]) for r in range(h) if len(set(a[r])) == 1 and a[r][0] != bg]
    sep_cols = [(c, a[0][c]) for c in range(w) if len({a[r][c] for r in range(h)}) == 1 and a[0][c] != bg]

    # A lone divider marks a repeated pattern extending from the panel before it.
    if len(sep_cols) == 1 and not sep_rows:
        c0, color = sep_cols[0]
        if c0 > 0:
            period = c0 + 1
            for r in range(h):
                source = a[r][:c0]
                for c in range(c0 + 1, w):
                    k = (c - (c0 + 1)) % period
                    a[r][c] = color if k == c0 else source[k]
        return a
    if len(sep_rows) == 1 and not sep_cols:
        r0, color = sep_rows[0]
        if r0 > 0:
            for r in range(r0 + 1, h):
                a[r] = a[r - r0 - 1][:]
        return a

    rowcuts = {r for r, _ in sep_rows}
    colcuts = {c for c, _ in sep_cols}
    row_blocks, col_blocks = [], []
    start = 0
    for r in range(h + 1):
        if r == h or r in rowcuts:
            if start < r: row_blocks.append((start, r))
            start = r + 1
    start = 0
    for c in range(w + 1):
        if c == w or c in colcuts:
            if start < c: col_blocks.append((start, c))
            start = c + 1
    if not row_blocks or not col_blocks:
        return a
    # The populated panel is the seed; copy it into every equally sized panel.
    candidates = []
    for ri, (r1, r2) in enumerate(row_blocks):
        for ci, (c1, c2) in enumerate(col_blocks):
            count = sum(a[r][c] != bg for r in range(r1, r2) for c in range(c1, c2))
            candidates.append((count, ri, ci))
    _, sr, sc = max(candidates)
    r1, r2 = row_blocks[sr]; c1, c2 = col_blocks[sc]
    seed = [a[r][c1:c2] for r in range(r1, r2)]
    for ra, rb in row_blocks:
        for ca, cb in col_blocks:
            if rb - ra == len(seed) and cb - ca == len(seed[0]):
                for i in range(len(seed)):
                    a[ra+i][ca:cb] = seed[i][:]
    return a
'''
